import React, { useEffect, useState } from "react";
import api from "../services/api";
import "../styles/Marketplace.css";

const MyLibrary = () => {
  const [pages, setPages] = useState([]);
  const userId = localStorage.getItem("userId");

  useEffect(() => {
    if (!userId) return;
    api
      .get(`/landing/my/${userId}`)
      .then(res => {
        console.log("📚 MyLibrary data:", res.data);
        setPages(res.data);
      })
      .catch(err => console.error("❌ Lỗi tải MyLibrary:", err));
  }, [userId]);

  return (
    <div className="my-library-page">
      <h1>Kho Landing Page của tôi</h1>
      <div className="templates-grid">
        {pages.length > 0 ? (
          pages.map(p => (
            <div key={p._id} className="template-card">
              <h3>{p.name}</h3>
              <iframe
                src={`http://localhost:5000${p.htmlPath}`}
                style={{ width: "100%", height: "300px", border: "1px solid #ddd" }}
                title={p.name}
              ></iframe>
            </div>
          ))
        ) : (
          <p>Chưa có landing nào được lưu.</p>
        )}
      </div>
    </div>
  );
};

export default MyLibrary;
